    expectedRenderPixelRatio: 1.75, graphics: { ...PRESET_VALUES.high, preset: 'high' },
    normalMode: 'production pixel normals (no waterNormals flag)', runtimeOverrides: [],
    sourceAudit: qualityMetadata(args.qualityBase) };
}

